# Remove duplicates by Word (case-insensitive)
seen = set()
unique = []
for w in words:
    key = w["Word"].lower()
    if key not in seen:
        seen.add(key)
        unique.append(w)

print(f"Total unique words: {len(unique)}")
with open(r"c:\Users\pcw06\Documents\Codex\JLPT-N2-Plan\scripts\toeic_tier1.json", "w", encoding="utf-8") as f:
    json.dump(unique, f, ensure_ascii=False, indent=2)
print(f"Wrote {len(unique)} words to toeic_tier1.json")
